#!/usr/bin/env node
// Condense a captured conversation JSONL into a readable digest.
// argv: <path-to-jsonl> [maxTextChars]
import { readFileSync } from 'node:fs';

const [file, maxArg] = process.argv.slice(2);
const MAX = Number(maxArg || 1200);

const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
const clip = (s) => (s.length > MAX ? s.slice(0, MAX) + `…[+${s.length - MAX}]` : s);

let prevTs = null;
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || e.ts || '';
  const gap = prevTs && ts ? Math.round((Date.parse(ts) - Date.parse(prevTs)) / 1000) : null;
  prevTs = ts || prevTs;
  const gapTag = gap && gap >= 20 ? ` [+${gap}s]` : '';
  const role = e.type || e.role || '';
  const msg = e.message || e;
  const content = msg?.content;

  if (role === 'user') {
    if (typeof content === 'string') {
      console.log(`\n=== USER ${ts}${gapTag} ===\n${clip(content)}`);
    } else if (Array.isArray(content)) {
      for (const c of content) {
        if (c.type === 'text') console.log(`\n=== USER ${ts}${gapTag} ===\n${clip(c.text)}`);
        else if (c.type === 'tool_result') {
          const t = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
          console.log(`  <- result${c.is_error ? ' ERROR' : ''}${gapTag}: ${clip((t || '').slice(0, 400))}`);
        }
      }
    }
  } else if (role === 'assistant') {
    if (Array.isArray(content)) {
      for (const c of content) {
        if (c.type === 'text' && c.text.trim()) console.log(`\n--- ASSISTANT ${ts}${gapTag} ---\n${clip(c.text)}`);
        else if (c.type === 'tool_use') {
          const input = JSON.stringify(c.input);
          console.log(`  -> ${c.name}${gapTag}: ${input.slice(0, 300)}`);
        }
      }
    }
  }
}

