#!/usr/bin/env node
// Print only the human turns of a captured conversation, with timestamps.
import { readFileSync } from 'node:fs';

for (const file of process.argv.slice(2)) {
  console.log(`\n########## ${file.split('/').pop()} ##########`);
  const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
  for (const line of lines) {
    let e;
    try { e = JSON.parse(line); } catch { continue; }
    const role = e.type || e.role;
    if (role !== 'user') continue;
    const content = e.message?.content ?? e.content;
    const texts = [];
    if (typeof content === 'string') texts.push(content);
    else if (Array.isArray(content)) for (const c of content) if (c.type === 'text') texts.push(c.text);
    for (const t of texts) {
      if (!t.trim()) continue;
      if (t.startsWith('<')) continue; // harness pseudo-turn wrapper
      if (/^\[Request interrupted/.test(t)) { console.log(`\n[${e.timestamp}] «INTERRUPTED»`); continue; }
      console.log(`\n[${e.timestamp}] ${t.slice(0, 2500)}`);
    }
  }
}

