#!/usr/bin/env node
// Surface friction signals from a captured conversation: tool errors, long gaps,
// hook blocks, and the assistant's own narration around them.
import { readFileSync } from 'node:fs';

const GAP = Number(process.env.GAP || 90);

for (const file of process.argv.slice(2)) {
  console.log(`\n########## ${file.split('/').pop()} ##########`);
  const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
  const entries = [];
  for (const line of lines) {
    try { entries.push(JSON.parse(line)); } catch { /* skip */ }
  }
  let prev = null;
  let toolCount = 0;
  const names = new Map();
  for (const e of entries) {
    const ts = e.timestamp;
    const gap = prev && ts ? Math.round((Date.parse(ts) - Date.parse(prev)) / 1000) : 0;
    if (ts) prev = ts;
    const role = e.type || e.role;
    const content = e.message?.content;
    if (!Array.isArray(content)) continue;
    for (const c of content) {
      if (role === 'assistant' && c.type === 'tool_use') {
        toolCount++;
        names.set(c.name, (names.get(c.name) || 0) + 1);
        if (gap >= GAP) console.log(`[gap ${gap}s before] -> ${c.name}: ${JSON.stringify(c.input).slice(0, 220)}`);
      }
      if (role === 'user' && c.type === 'tool_result') {
        const t = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
        if (c.is_error || /error|Blocked|denied|BLOCKING|refus/i.test(t || '')) {
          console.log(`  <<ERR/BLOCK ${e.timestamp}>> ${(t || '').replace(/\s+/g, ' ').slice(0, 500)}`);
        }
        if (gap >= GAP) console.log(`  <<slow result ${gap}s>> ${(t || '').replace(/\s+/g, ' ').slice(0, 160)}`);
      }
      if (role === 'assistant' && c.type === 'text' && /wrong|mistake|actually|correct(ed|ion)?|instead|retry|re-?ran|backtrack|misread/i.test(c.text)) {
        console.log(`  ~~note ${e.timestamp}: ${c.text.replace(/\s+/g, ' ').slice(0, 400)}`);
      }
    }
  }
  const first = entries.find((e) => e.timestamp)?.timestamp;
  const last = [...entries].reverse().find((e) => e.timestamp)?.timestamp;
  console.log(`\n[summary] entries=${entries.length} tools=${toolCount} span=${first} → ${last}`);
  console.log(`[tools] ${[...names.entries()].sort((a, b) => b[1] - a[1]).map(([n, c]) => `${n}:${c}`).join(' ')}`);
}

